Status: 200 OK | Content-Type: text/plain; charset=utf-8 | Size: 71,015 bytes

Based on the provided kernel driver source code, here is the requested information regarding Netlink multicast usage, `NBD_CMD_RECONFIGURE`, and `NBD_ATTR_DEAD_CONN_TIMEOUT`.

### 1. Netlink Multicast Usage

*   **Multicast Group:** Messages are sent to the group defined by `NBD_GENL_MCAST_GROUP_NAME` (registered in `nbd_mcast_grps`).
*   **Command Used:** `NBD_CMD_LINK_DEAD`
*   **Attributes Carried:** `NBD_ATTR_INDEX` (Type: `NLA_U32`)
*   **Condition for Sending:** The message is sent when a socket connection is marked as dead (`nbd_mark_nsock_dead`), specifically when:
    1.  The socket was not previously marked dead (`!nsock->dead`).
    2.  Notification is requested (`notify` argument is true).
    3.  The device is not already fully disconnected or in the process of disconnecting (`!nbd_disconnected(nbd->config)`).

This logic is handled asynchronously via the work function `nbd_dead_link_work`, which calls `nbd_mcast_index`.

**Relevant Code Snippets:**

```c
static void nbd_mcast_index(int index)
{
	struct sk_buff *skb;
	void *msg_head;
	int ret;

	skb = genlmsg_new(nla_total_size(sizeof(u32)), GFP_KERNEL);
	if (!skb)
		return;
	msg_head = genlmsg_put(skb, 0, 0, &nbd_genl_family, 0,
				     NBD_CMD_LINK_DEAD);
	if (!msg_head) {
		nlmsg_free(skb);
		return;
	}
	ret = nla_put_u32(skb, NBD_ATTR_INDEX, index);
	if (ret) {
		nlmsg_free(skb);
		return;
	}
	genlmsg_end(skb, msg_head);
	genlmsg_multicast(&nbd_genl_family, skb, 0, 0, GFP_KERNEL);
}

static void nbd_dead_link_work(struct work_struct *work)
{
	struct link_dead_args *args = container_of(work, struct link_dead_args,
						   work);
	nbd_mcast_index(args->index);
	kfree(args);
}

static void nbd_mark_nsock_dead(struct nbd_device *nbd, struct nbd_sock *nsock,
				int notify)
{
	if (!nsock->dead && notify && !nbd_disconnected(nbd->config)) {
		struct link_dead_args *args;
		args = kmalloc_obj(struct link_dead_args, GFP_NOIO);
		if (args) {
			INIT_WORK(&args->work, nbd_dead_link_work);
			args->index = nbd->index;
			queue_work(system_percpu_wq, &args->work);
		}
	}
    /* ... */
}
```

### 2. NBD_CMD_RECONFIGURE Behavior on Unconfigured Device

If `NBD_CMD_RECONFIGURE` is issued against a device that is no longer configured (either `nbd_get_config_unlocked` returns NULL or the `NBD_RT_BOUND` flag is unset/PID is missing), it returns **`-EINVAL`**.

**Relevant Code Snippet:**

```c
	config = nbd_get_config_unlocked(nbd);
	if (!config) {
		dev_err(nbd_to_dev(nbd),
			"not configured, cannot reconfigure\n");
		nbd_put(nbd);
		return -EINVAL;
	}

	mutex_lock(&nbd->config_lock);
	if (!test_bit(NBD_RT_BOUND, &config->runtime_flags) ||
	    !nbd->pid) {
		dev_err(nbd_to_dev(nbd),
			"not configured, cannot reconfigure\n");
		ret = -EINVAL;
		goto out;
	}
```

### 3. NBD_ATTR_DEAD_CONN_TIMEOUT Functionality

`NBD_ATTR_DEAD_CONN_TIMEOUT` sets the duration (in seconds, converted to jiffies internally) that the driver will wait for a new connection to be established before failing I/O requests when all current connections are dead.

It is stored in `config->dead_conn_timeout` and used in `wait_for_reconnect()`. If this timeout expires without a live connection appearing or a disconnect being requested, pending I/O operations fail with `BLK_STS_IOERR`.

**Relevant Code Snippets:**

```c
/* In nbd_genl_connect and nbd_genl_reconfigure */
	if (info->attrs[NBD_ATTR_DEAD_CONN_TIMEOUT]) {
		config->dead_conn_timeout =
			nla_get_u64(info->attrs[NBD_ATTR_DEAD_CONN_TIMEOUT]);
		config->dead_conn_timeout *= HZ;
	}

/* Usage in wait_for_reconnect */
static int wait_for_reconnect(struct nbd_device *nbd)
{
	struct nbd_config *config = nbd->config;
	if (!config->dead_conn_timeout)
		return 0;

	if (!wait_event_timeout(config->conn_wait,
				test_bit(NBD_RT_DISCONNECTED,
					 &config->runtime_flags) ||
				atomic_read(&config->live_connections) > 0,
				config->dead_conn_timeout))
		return 0;

	return !test_bit(NBD_RT_DISCONNECTED, &config->runtime_flags);
}
```

