			fprintf(stderr, "Successfully reconnected after %d attempts\n", attempt + 1);
			return 0;
		}

		backoff_time *= 2;
		attempt++;
	}

	fprintf(stderr, "Failed to reconnect after %d attempts, giving up\n", attempt);
	return -1;
}
