/* Persist mode main loop: stay around after connecting, listen for link
 * events on the nbd netlink multicast group, and when a connection is
 * reported dead, reconnect with backoff and swap the new sockets into
 * the kernel with NBD_CMD_RECONFIGURE */
static int persist_mode_main(int device_index, uint16_t connection_flags,
			     const char *identifier) {
	struct nl_sock *mcast_socket = NULL;
	persist_connection_t persist_conn;
	struct sigaction sa;
	int driver_id;
	int grp_id;
	int ret;

	memset(&persist_conn, 0, sizeof(persist_connection_t));
	persist_conn.conn = malloc(sizeof(saved_connection_t));
	if (!persist_conn.conn)
		err("Cannot allocate saved connection\n");

	memset(persist_conn.conn, 0, sizeof(saved_connection_t));
	persist_conn.flags = connection_flags;
	persist_conn.size64 = cur_client->size64;
	persist_conn.blocksize = cur_client->bs;
	persist_conn.timeout = cur_client->timeout;
	if (device_index < 0)
		device_index = connected_index;
	persist_conn.device_index = device_index;

	/* Save initial connection details */
	if (!cur_client->b_unix) {
		int sock;

		persist_conn.conn->hostname = strdup(cur_client->hostn);
		persist_conn.conn->port = strdup(cur_client->port);
		/* Perform initial address resolution and save the result,
		 * so that reconnection attempts don't need to re-resolve */
		sock = opennet(persist_conn.conn);
		if (sock >= 0)
			close(sock);
	}

	/* Set up signal handling for clean shutdown */
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = persist_signal_handler;
	sigaction(SIGINT, &sa, NULL);
	sigaction(SIGTERM, &sa, NULL);

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = SIG_IGN;
	sigaction(SIGPIPE, &sa, NULL);

	/* Set up multicast socket for listening to link events */
	mcast_socket = nl_socket_alloc();
	if (!mcast_socket)
		err("Couldn't allocate multicast socket\n");

	if (genl_connect(mcast_socket))
		err("Couldn't connect to the generic netlink socket\n");

	/* Multicast messages are unsolicited and carry no sequence
	 * number we could match, so disable the sequence check to
	 * avoid them being dropped */
	nl_socket_disable_seq_check(mcast_socket);

	driver_id = genl_ctrl_resolve(mcast_socket, "nbd");
	if (driver_id < 0)
		err("Couldn't resolve the nbd netlink family for multicast\n");

	/* Join multicast group */
	grp_id = genl_ctrl_resolve_grp(mcast_socket, NBD_GENL_FAMILY_NAME,
				       NBD_GENL_MCAST_GROUP_NAME);
	if (grp_id < 0)
		err("Couldn't resolve the nbd netlink multicast group\n");
	ret = nl_socket_add_membership(mcast_socket, grp_id);
	if (ret < 0)
		err("Couldn't join nbd multicast group\n");

	/* Set up callback for multicast messages */
	nl_socket_modify_cb(mcast_socket, NL_CB_VALID, NL_CB_CUSTOM, persist_callback, &persist_conn);

	fprintf(stderr, "Persist mode active, monitoring device %d\n", device_index);

	/* Main monitoring loop */
	while (!persist_stop) {
		struct pollfd pfd;
		struct timespec timeout_ts = { .tv_sec = 1, .tv_nsec = 0 };

		pfd.fd = nl_socket_get_fd(mcast_socket);
		pfd.events = POLLIN;
		pfd.revents = 0;

		/* Wait for multicast messages or timeout */
		ret = ppoll(&pfd, 1, &timeout_ts, NULL);

		if (persist_stop)
			break;

		if (ret > 0 && (pfd.revents & POLLIN)) {
			/* Process netlink messages */
			nl_recvmsgs_default(mcast_socket);
		} else if (ret < 0 && errno != EINTR) {
			/* Not being able to poll the netlink socket is
			 * unusual; sleep briefly to avoid busy-looping, then
			 * try again */
			err_nonfatal("Poll failed in persist mode: %m");
			sleep(1);
		} else if (ret > 0 && (pfd.revents & POLLNVAL)) {
			/* The fd is unusable; wait a bit before retrying */
			sleep(1);
		}

		if (persist_conn.link_dead) {
			int *new_sockfds;
			int i;

			persist_conn.link_dead = 0;
			new_sockfds = malloc(sizeof(int) * cur_client->nconn);
			if (!new_sockfds)
				err("Cannot allocate the socket fd's array");
			if (reconnect_with_backoff(&persist_conn, new_sockfds) == 0) {
				if (persist_conn.device_index >= 0) {
					if (netlink_reconfigure(persist_conn.device_index, new_sockfds) < 0) {
						/* The device was probably
						 * disconnected while we were
						 * reconnecting; set it up
						 * from scratch instead */
						netlink_configure(persist_conn.device_index, new_sockfds, persist_conn.flags, identifier);
					}
				} else {
					fprintf(stderr, "Cannot reconfigure: device index unknown\n");
				}
				/* The kernel holds its own reference to the
				 * sockets; drop our copies */
				for (i = 0; i < cur_client->nconn; i++) {
					if (new_sockfds[i] >= 0)
						close(new_sockfds[i]);
				}
			} else if (!persist_stop) {
				fprintf(stderr, "Giving up on reconnecting device %d\n", device_index);
			}
			free(new_sockfds);
		}
	}

	if (persist_stop)
		fprintf(stderr, "Received interrupt signal, shutting down persist mode\n");

	/* Cleanup */
	cleanup_persist_connection(&persist_conn);

	if (mcast_socket) {
		nl_socket_free(mcast_socket);
	}

	return 0;
}

